import { useState, useEffect } from 'react';
import { fetchAnalyticsData } from '../services/analyticsService';

type AnalyticsData = {
  date: string;
  pageViews: number;
  uniqueVisitors: number;
  bounceRate: number;
  avgSessionDuration: number;
  topPages: { page: string; views: number }[];
  trafficSources: { source: string; percentage: number }[];
  devices: { device: string; percentage: number }[];
};

export const useAnalyticsData = (dateRange: { start: string; end: string }) => {
  const [data, setData] = useState<AnalyticsData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadData = async () => {
      try {
        setLoading(true);
        const response = await fetchAnalyticsData(dateRange);
        setData(response);
      } catch (err) {
        setError('Failed to fetch analytics data');
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [dateRange]);

  return { data, loading, error };
};

src/hooks/useProjectTasks.ts:
import { useState, useEffect } from 'react';
import { projectService } from '../services/projectService';

type Task = {
  id: string;
  title: string;
  description: string;
  status: 'todo' | 'in-progress' | 'done';
  priority: 'low' | 'medium' | 'high';
  dueDate: string;
  assignedTo: string;
};

type Project = {
  id: string;
  name: string;
  description: string;
  tasks: Task[];
};

export const useProjectTasks = (projectId: string) => {
  const [project, setProject] = useState<Project | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchProjectTasks = async () => {
      try {
        setLoading(true);
        const data = await projectService.getProjectTasks(projectId);
        setProject(data);
      } catch (err) {
        setError('Failed to fetch project tasks');
      } finally {
        setLoading(false);
      }
    };

    fetchProjectTasks();
  }, [projectId]);

  const updateTaskStatus = async (taskId: string, newStatus: Task['status']) => {
    if (!project) return;

    try {
      await projectService.updateTaskStatus(projectId, taskId, newStatus);
      setProject({
        ...project,
        tasks: project.tasks.map(task =>
          task.id === taskId ? { ...task, status: newStatus } : task
        ),
      });
    } catch (err) {
      setError('Failed to update task status');
    }
  };

  const addTask = async (task: Omit<Task, 'id'>) => {
    if (!project) return;

    try {
      const newTask = await projectService.addTask(projectId, task);
      setProject({
        ...project,
        tasks: [...project.tasks, newTask],
      });
    } catch (err) {
      setError('Failed to add task');
    }
  };

  return {
    project,
    loading,
    error,
    updateTaskStatus,
    addTask,
  };
};

