import React, { useState, useEffect } from 'react';
import { KanbanBoard, TaskList, GanttChart, TeamMembers, ProjectTimeline, FileUploader, CommentsSection, MilestoneTracker, ResourceAllocationChart, ProjectOverviewCard } from '../../components/ProjectManagement';
import styles from './ProjectManagement.module.css';
import { useProjectTasks } from '../../hooks/useProjectTasks';
import { fetchProjectData } from '../../services/projectService';

type ProjectData = {
  id: string;
  name: string;
  description: string;
  startDate: string;
  endDate: string;
  status: 'Not Started' | 'In Progress' | 'Completed' | 'On Hold';
  teamMembers: Array<{
    id: string;
    name: string;
    role: string;
    avatar: string;
  }>;
  milestones: Array<{
    id: string;
    name: string;
    dueDate: string;
    status: 'Pending' | 'Completed' | 'Delayed';
  }>;
  tasks: Array<{
    id: string;
    title: string;
    description: string;
    assignee: string;
    status: 'To Do' | 'In Progress' | 'Done';
    priority: 'Low' | 'Medium' | 'High';
    dueDate: string;
  }>;
  resources: Array<{
    id: string;
    name: string;
    type: 'Person' | 'Equipment' | 'Material';
    allocation: number;
  }>;
  files: Array<{
    id: string;
    name: string;
    type: string;
    size: string;
    uploadedBy: string;
    date: string;
  }>;
  comments: Array<{
    id: string;
    author: string;
    text: string;
    date: string;
  }>;
};

const ProjectManagementPage: React.FC = () => {
  const [projectData, setProjectData] = useState<ProjectData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { tasks, updateTaskStatus } = useProjectTasks();

  useEffect(() => {
    const loadProjectData = async () => {
      try {
        const data = await fetchProjectData('project-123');
        setProjectData(data);
      } catch (err) {
        setError('Failed to load project data');
      } finally {
        setLoading(false);
      }
    };

    loadProjectData();
  }, []);

  const handleFileUpload = (file: File) => {
    console.log('Uploading file:', file.name);
    // TODO: Implement file upload logic
  };

  const handleAddComment = (commentText: string) => {
    if (!projectData) return;

    const newComment = {
      id: `comment-${Date.now()}`,
      author: 'Current User',
      text: commentText,
      date: new Date().toISOString(),
    };

    setProjectData({
      ...projectData,
      comments: [...projectData.comments, newComment],
    });
  };

  if (loading) return <div>Loading project data...</div>;
  if (error) return <div>Error: {error}</div>;
  if (!projectData) return <div>No project data available</div>;

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h1>{projectData.name}</h1>
        <p>{projectData.description}</p>
      </div>

      <div className={styles.grid}>
        <div className={styles.overviewSection}>
          <ProjectOverviewCard 
            startDate={projectData.startDate} 
            endDate={projectData.endDate} 
            status={projectData.status} 
          />
        </div>

        <div className={styles.kanbanSection}>
          <KanbanBoard 
            tasks={tasks} 
            onTaskStatusChange={updateTaskStatus} 
          />
        </div>

        <div className={styles.timelineSection}>
          <ProjectTimeline 
            milestones={projectData.milestones} 
          />
        </div>

        <div className={styles.ganttSection}>
          <GanttChart 
            tasks={projectData.tasks} 
          />
        </div>

        <div className={styles.teamSection}>
          <TeamMembers 
            members={projectData.teamMembers} 
          />
        </div>

        <div className={styles.resourcesSection}>
          <ResourceAllocationChart 
            resources={projectData.resources} 
          />
        </div>

        <div className={styles.filesSection}>
          <FileUploader 
            files={projectData.files} 
            onUpload={handleFileUpload} 
          />
        </div>

        <div className={styles.commentsSection}>
          <CommentsSection 
            comments={projectData.comments} 
            onAddComment={handleAddComment} 
          />
        </div>

        <div className={styles.milestonesSection}>
          <MilestoneTracker 
            milestones={projectData.milestones} 
          />
        </div>

        <div className={styles.taskListSection}>
          <TaskList 
            tasks={projectData.tasks} 
          />
        </div>
      </div>
    </div>
  );
};

export default ProjectManagementPage;

