import React, { useState, useEffect } from 'react';
import { Card, Spin, Typography } from 'antd';
import { CloudOutlined, SunOutlined, ThunderboltOutlined } from '@ant-design/icons';

const { Text } = Typography;

type WeatherData = {
  temperature: number;
  condition: string;
  humidity: number;
  windSpeed: number;
  icon: React.ReactNode;
};

export const WeatherWidget: React.FC = () => {
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    // Simulate API call
    const fetchWeather = () => {
      setTimeout(() => {
        const conditions = ['Sunny', 'Cloudy', 'Thunderstorm'];
        const randomCondition = conditions[Math.floor(Math.random() * conditions.length)];

        let icon;
        switch (randomCondition) {
          case 'Sunny':
            icon = <SunOutlined style={{ color: '#FFD700', fontSize: '24px' }} />;
            break;
          case 'Cloudy':
            icon = <CloudOutlined style={{ color: '#A9A9A9', fontSize: '24px' }} />;
            break;
          case 'Thunderstorm':
            icon = <ThunderboltOutlined style={{ color: '#800080', fontSize: '24px' }} />;
            break;
          default:
            icon = <SunOutlined style={{ color: '#FFD700', fontSize: '24px' }} />;
        }

        setWeather({
          temperature: Math.floor(Math.random() * 30) + 10,
          condition: randomCondition,
          humidity: Math.floor(Math.random() * 100),
          windSpeed: Math.floor(Math.random() * 20) + 5,
          icon
        });
        setLoading(false);
      }, 1000);
    };

    fetchWeather();
  }, []);

  return (
    <Card title="Weather" bordered={false} style={{ width: '100%' }}>
      {loading ? (
        <Spin />
      ) : weather ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
            {weather.icon}
            <Text strong style={{ fontSize: '24px' }}>{weather.temperature}°C</Text>
          </div>
          <Text>{weather.condition}</Text>
          <div style={{ display: 'flex', justifyContent: 'space-between' }}>
            <Text>Humidity: {weather.humidity}%</Text>
            <Text>Wind: {weather.windSpeed} km/h</Text>
          </div>
        </div>
      ) : (
        <Text>Weather data unavailable</Text>
      )}
    </Card>
  );
};

