import { useState } from 'react';
import { Button, Form, Input, DatePicker, Select, Upload, message } from 'antd';
import { UploadOutlined } from '@ant-design/icons';

const { Option } = Select;
const { TextArea } = Input;

interface ProfileData {
  firstName: string;
  lastName: string;
  email: string;
  bio: string;
  birthDate: string;
  gender: string;
  location: string;
  website: string;
  avatar: any[];
}

export const EditableProfileForm = () => {
  const [form] = Form.useForm();
  const [isEditing, setIsEditing] = useState(false);
  const [profileData, setProfileData] = useState<ProfileData>({
    firstName: 'Alex',
    lastName: 'Johnson',
    email: 'alex.johnson@example.com',
    bio: 'Senior UX Designer with 8 years of experience creating intuitive user interfaces for enterprise applications.',
    birthDate: '1990-05-15',
    gender: 'male',
    location: 'San Francisco, CA',
    website: 'alexjohnson.design',
    avatar: [],
  });

  const handleEdit = () => {
    setIsEditing(true);
  };

  const handleSave = (values: ProfileData) => {
    setProfileData(values);
    setIsEditing(false);
    message.success('Profile updated successfully!');
  };

  const handleCancel = () => {
    form.resetFields();
    setIsEditing(false);
  };

  const uploadProps = {
    beforeUpload: (file: File) => {
      const isJpgOrPng = file.type === 'image/jpeg' || file.type === 'image/png';
      if (!isJpgOrPng) {
        message.error('You can only upload JPG/PNG files!');
      }
      const isLt2M = file.size / 1024 / 1024 < 2;
      if (!isLt2M) {
        message.error('Image must be smaller than 2MB!');
      }
      return isJpgOrPng && isLt2M;
    },
    onChange: (info: any) => {
      if (info.file.status === 'done') {
        message.success(`${info.file.name} file uploaded successfully`);
        form.setFieldsValue({ avatar: [info.file] });
      }
    },
  };

  return (
    <div className="editable-profile-form">
      <Form
        form={form}
        layout="vertical"
        initialValues={profileData}
        onFinish={handleSave}
        disabled={!isEditing}
      >
        <div className="form-header">
          <h2>Profile Information</h2>
          {!isEditing ? (
            <Button type="primary" onClick={handleEdit}>
              Edit Profile
            </Button>
          ) : (
            <div className="form-actions">
              <Button type="primary" htmlType="submit">
                Save Changes
              </Button>
              <Button onClick={handleCancel}>Cancel</Button>
            </div>
          )}
        </div>

        <Form.Item
          name="avatar"
          label="Profile Picture"
          valuePropName="fileList"
          getValueFromEvent={(e) => (Array.isArray(e) ? e : e?.fileList)}
        >
          <Upload name="avatar" listType="picture" maxCount={1} {...uploadProps}>
            <Button icon={<UploadOutlined />}>Upload Photo</Button>
          </Upload>
        </Form.Item>

        <div className="form-row">
          <Form.Item
            name="firstName"
            label="First Name"
            rules={[{ required: true, message: 'Please input your first name!' }]}
            className="form-col"
          >
            <Input />
          </Form.Item>

          <Form.Item
            name="lastName"
            label="Last Name"
            rules={[{ required: true, message: 'Please input your last name!' }]}
            className="form-col"
          >
            <Input />
          </Form.Item>
        </div>

        <Form.Item
          name="email"
          label="Email"
          rules={[
            { required: true, message: 'Please input your email!' },
            { type: 'email', message: 'Please enter a valid email!' },
          ]}
        >
          <Input />
        </Form.Item>

        <Form.Item name="bio" label="Bio">
          <TextArea rows={4} />
        </Form.Item>

        <div className="form-row">
          <Form.Item
            name="birthDate"
            label="Birth Date"
            className="form-col"
          >
            <DatePicker style={{ width: '100%' }} />
          </Form.Item>

          <Form.Item name="gender" label="Gender" className="form-col">
            <Select>
              <Option value="male">Male</Option>
              <Option value="female">Female</Option>
              <Option value="other">Other</Option>
              <Option value="prefer-not-to-say">Prefer not to say</Option>
            </Select>
          </Form.Item>
        </div>

        <Form.Item name="location" label="Location">
          <Input />
        </Form.Item>

        <Form.Item
          name="website"
          label="Website"
          rules={[
            { type: 'url', message: 'Please enter a valid URL (include http:// or https://)' },
          ]}
        >
          <Input />
        </Form.Item>
      </Form>
    </div>
  );
};

