import React, { useState } from 'react';
import { Image, Row, Col, Button, Modal } from 'antd';
import { LeftOutlined, RightOutlined, DeleteOutlined, DownloadOutlined } from '@ant-design/icons';

interface Photo {
  id: string;
  url: string;
  caption: string;
  date: string;
  location: string;
}

const PhotoGallery: React.FC = () => {
  const [photos, setPhotos] = useState<Photo[]>([
    {
      id: '1',
      url: 'https://example.com/photo1.jpg',
      caption: 'Team building at the annual retreat',
      date: '2023-05-15',
      location: 'Lake Tahoe, CA'
    },
    {
      id: '2',
      url: 'https://example.com/photo2.jpg',
      caption: 'Presenting at the Tech Conference',
      date: '2023-03-22',
      location: 'San Francisco, CA'
    },
    {
      id: '3',
      url: 'https://example.com/photo3.jpg',
      caption: 'Project launch celebration',
      date: '2023-01-10',
      location: 'New York, NY'
    },
    {
      id: '4',
      url: 'https://example.com/photo4.jpg',
      caption: 'Workshop with the design team',
      date: '2022-11-05',
      location: 'Austin, TX'
    }
  ]);

  const [previewVisible, setPreviewVisible] = useState(false);
  const [previewImage, setPreviewImage] = useState('');
  const [previewTitle, setPreviewTitle] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);

  const handlePreview = (photo: Photo, index: number) => {
    setPreviewImage(photo.url);
    setPreviewTitle(photo.caption);
    setPreviewVisible(true);
    setCurrentIndex(index);
  };

  const handleDelete = (id: string) => {
    setPhotos(photos.filter(photo => photo.id !== id));
  };

  const navigateImage = (direction: 'prev' | 'next') => {
    let newIndex;
    if (direction === 'prev') {
      newIndex = currentIndex === 0 ? photos.length - 1 : currentIndex - 1;
    } else {
      newIndex = currentIndex === photos.length - 1 ? 0 : currentIndex + 1;
    }
    setCurrentIndex(newIndex);
    setPreviewImage(photos[newIndex].url);
    setPreviewTitle(photos[newIndex].caption);
  };

  return (
    <div className="photo-gallery">
      <Row gutter={[16, 16]}>
        {photos.map((photo, index) => (
          <Col key={photo.id} xs={12} sm={8} md={6} lg={4}>
            <div className="photo-thumbnail">
              <Image
                src={photo.url}
                alt={photo.caption}
                preview={false}
                onClick={() => handlePreview(photo, index)}
              />
              <div className="photo-meta">
                <p>{photo.caption}</p>
                <small>{photo.date} • {photo.location}</small>
              </div>
            </div>
          </Col>
        ))}
      </Row>

      <Modal
        visible={previewVisible}
        title={previewTitle}
        footer={[
          <Button key="download" icon={<DownloadOutlined />}>
            Download
          </Button>,
          <Button 
            key="delete" 
            icon={<DeleteOutlined />} 
            danger
            onClick={() => {
              handleDelete(photos[currentIndex].id);
              setPreviewVisible(false);
            }}
          >
            Delete
          </Button>
        ]}
        onCancel={() => setPreviewVisible(false)}
        width="80%"
      >
        <div className="image-navigation">
          <Button 
            icon={<LeftOutlined />} 
            onClick={() => navigateImage('prev')}
            className="nav-button"
          />
          <Image
            src={previewImage}
            alt={previewTitle}
            style={{ maxHeight: '70vh', objectFit: 'contain' }}
          />
          <Button 
            icon={<RightOutlined />} 
            onClick={() => navigateImage('next')}
            className="nav-button"
          />
        </div>
      </Modal>
    </div>
  );
};

export default PhotoGallery;

