  email: boolean;
  push: boolean;
  frequency: 'instant' | 'daily' | 'weekly';
};

type PrivacySetting = {
  profileVisibility: 'public' | 'friends' | 'private';
  activityVisibility: boolean;
  searchEngineIndexing: boolean;
};

type SecuritySetting = {
  twoFactorAuth: boolean;
  backupEmail: string;
};

type LanguageSetting = {
  language: string;
  timezone: string;
};

export const SettingsAccordion = () => {
  const [notificationSettings, setNotificationSettings] = useState<NotificationSetting>({
    email: true,
    push: false,
    frequency: 'daily',
  });

  const [privacySettings, setPrivacySettings] = useState<PrivacySetting>({
    profileVisibility: 'friends',
    activityVisibility: true,
    searchEngineIndexing: false,
  });

  const [securitySettings, setSecuritySettings] = useState<SecuritySetting>({
    twoFactorAuth: false,
    backupEmail: 'backup@example.com',
  });

  const [languageSettings, setLanguageSettings] = useState<LanguageSetting>({
    language: 'en-US',
    timezone: 'America/New_York',
  });

  const handleNotificationChange = (key: keyof NotificationSetting, value: any) => {
    setNotificationSettings(prev => ({ ...prev, [key]: value }));
  };

  const handlePrivacyChange = (key: keyof PrivacySetting, value: any) => {
    setPrivacySettings(prev => ({ ...prev, [key]: value }));
  };

  const handleSecurityChange = (key: keyof SecuritySetting, value: any) => {
    setSecuritySettings(prev => ({ ...prev, [key]: value }));
  };

  const handleLanguageChange = (key: keyof LanguageSetting, value: string) => {
    setLanguageSettings(prev => ({ ...prev, [key]: value }));
  };

  return (
    <Collapse accordion defaultActiveKey={['1']}>
      <Panel header="Notification Settings" key="1" extra={<BellOutlined />}>
        <div className="setting-item">
          <span>Email Notifications</span>
          <Switch 
            checked={notificationSettings.email} 
            onChange={(checked) => handleNotificationChange('email', checked)} 
          />
        </div>
        <div className="setting-item">
          <span>Push Notifications</span>
          <Switch 
            checked={notificationSettings.push} 
            onChange={(checked) => handleNotificationChange('push', checked)} 
          />
        </div>
        <div className="setting-item">
          <span>Notification Frequency</span>
          <Select
            value={notificationSettings.frequency}
            onChange={(value) => handleNotificationChange('frequency', value)}
            style={{ width: 120 }}
          >
            <Option value="instant">Instant</Option>
            <Option value="daily">Daily</Option>
            <Option value="weekly">Weekly</Option>
          </Select>
        </div>
      </Panel>

      <Panel header="Privacy Settings" key="2" extra={<LockOutlined />}>
        <div className="setting-item">
          <span>Profile Visibility</span>
          <Select
            value={privacySettings.profileVisibility}
            onChange={(value) => handlePrivacyChange('profileVisibility', value)}
            style={{ width: 120 }}
          >
            <Option value="public">Public</Option>
            <Option value="friends">Friends Only</Option>
            <Option value="private">Private</Option>
          </Select>
        </div>
        <div className="setting-item">
          <span>Show Activity Status</span>
          <Switch 
            checked={privacySettings.activityVisibility} 
            onChange={(checked) => handlePrivacyChange('activityVisibility', checked)} 
          />
        </div>
        <div className="setting-item">
          <span>Search Engine Indexing</span>
          <Switch 
            checked={privacySettings.searchEngineIndexing} 
            onChange={(checked) => handlePrivacyChange('searchEngineIndexing', checked)} 
          />
        </div>
      </Panel>

      <Panel header="Security Settings" key="3" extra={<LockOutlined />}>
        <div className="setting-item">
          <span>Two-Factor Authentication</span>
          <Switch 
            checked={securitySettings.twoFactorAuth} 
            onChange={(checked) => handleSecurityChange('twoFactorAuth', checked)} 
          />
        </div>
        <div className="setting-item">
          <span>Backup Email</span>
          <Input 
            value={securitySettings.backupEmail} 
            onChange={(e) => handleSecurityChange('backupEmail', e.target.value)} 
            prefix={<MailOutlined />} 
          />
        </div>
      </Panel>

      <Panel header="Language & Region" key="4" extra={<GlobalOutlined />}>
        <div className="setting-item">
          <span>Language</span>
          <Select
            value={languageSettings.language}
            onChange={(value) => handleLanguageChange('language', value)}
            style={{ width: 120 }}
          >
            <Option value="en-US">English (US)</Option>
            <Option value="es-ES">Spanish</Option>
            <Option value="fr-FR">French</Option>
            <Option value="de-DE">German</Option>
          </Select>
        </div>
        <div className="setting-item">
          <span>Timezone</span>
          <Select
            value={languageSettings.timezone}
            onChange={(value) => handleLanguageChange('timezone', value)}
            style={{ width: 200 }}
          >
            <Option value="America/New_York">New York (EST)</Option>
            <Option value="America/Chicago">Chicago (CST)</Option>
            <Option value="America/Denver">Denver (MST)</Option>
            <Option value="America/Los_Angeles">Los Angeles (PST)</Option>
            <Option value="Europe/London">London (GMT)</Option>
          </Select>
        </div>
      </Panel>
    </Collapse>
  );
};

