import React from 'react';

type TrendIndicatorProps = {
  currentValue: number;
  previousValue: number;
  label: string;
};

export const TrendIndicator: React.FC<TrendIndicatorProps> = ({ 
  currentValue, 
  previousValue, 
  label 
}) => {
  const difference = currentValue - previousValue;
  const percentage = previousValue !== 0 
    ? (difference / previousValue) * 100 
    : 0;

  const isPositive = difference >= 0;
  const arrow = isPositive ? '↑' : '↓';

  return (
    <div className="trend-indicator">
      <h3>{label}</h3>
      <div className={`trend-value ${isPositive ? 'positive' : 'negative'}`}>
        <span>{currentValue.toLocaleString()}</span>
        <span className="trend-arrow">
          {arrow} {Math.abs(percentage).toFixed(1)}%
        </span>
      </div>
      <p className="trend-description">
        {isPositive ? 'Up' : 'Down'} by {Math.abs(difference).toLocaleString()} 
        from previous period
      </p>
    </div>
  );
};

